        }
        s_pf_last_pump_cyc = now_cyc;
    }

    for (n = 0; n < max_tiles && view->pump_phase != 0; n++) {
        if (n > 0 && lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
